// node --test .github/scripts/fenetre-verification.mjs
import { test } from "node:test";
import assert from "node:assert/strict";
import { champDuLibelle, milieu } from "./fenetre.mjs";

// La fenêtre de connexion telle que la décrit UI Automation sur la machine de GitHub (SimplySign Desktop 9.4.4.92).
const el = (nom, x, y, largeur, hauteur, main = false) => ({ nom, x, y, largeur, hauteur, main });
const FENETRE = [
  el("ver. 7.6.92.0", 700, 620, 80, 14),
  el("Token generated by the SimplySign", 760, 560, 220, 14),
  el("Your e-mail address", 760, 500, 160, 14),
  el("Login", 640, 430, 60, 20),
  el("Cancel", 860, 600, 80, 26, true),
  el("Ok", 770, 600, 80, 26, true),
  el("", 760, 532, 260, 24, true), // le champ du code, qui a la main au lancement
  el("Token:", 690, 536, 60, 16),
  el("", 760, 472, 260, 24, true), // le champ de l'adresse
  el("ID:", 690, 476, 40, 16),
];

test("chaque champ se trouve à droite de son libellé, sur la même ligne", () => {
  assert.deepEqual(milieu(champDuLibelle(FENETRE, "ID:")), { x: 890, y: 484 });
  assert.deepEqual(milieu(champDuLibelle(FENETRE, "Token:")), { x: 890, y: 544 });
});

test("un champ sous son libellé, faute de mieux ; rien sans libellé", () => {
  const empiles = [el("ID:", 100, 100, 30, 16), el("", 100, 122, 200, 24, true), el("Token:", 100, 160, 50, 16), el("", 100, 182, 200, 24, true)];
  assert.equal(champDuLibelle(empiles, "ID:").y, 122);
  assert.equal(champDuLibelle(empiles, "Token:").y, 182);
  assert.equal(champDuLibelle(empiles, "Mot de passe:"), null);
  assert.equal(champDuLibelle([el("ID:", 0, 0, 30, 16)], "ID:"), null);
});
